// Sierpinski renderer (data generated by 3 backend nodes)

const canvas = document.getElementById('sierpinski-canvas');
const ctx = canvas.getContext('2d');
const statsEl = document.getElementById('sierpinski-stats');

function drawTriangles(triangles) {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = '#f8fafc';
  triangles.forEach((t) => {
    ctx.beginPath();
    ctx.moveTo(t[0], t[1]);
    ctx.lineTo(t[2], t[3]);
    ctx.lineTo(t[4], t[5]);
    ctx.closePath();
    ctx.fill();
  });
}

function formatStats(stats) {
  if (!stats) return 'Esperando nodos...';
  return `Nodos: ${stats.nodes} | Turno: ${stats.turn_node || 'n/a'} | Triangulos: ${stats.total_triangles} | Ultima tarea: ${stats.last_task_id ?? 'n/a'}`;
}

async function fetchData() {
  try {
    const res = await fetch('/api/sierpinski/data');
    if (!res.ok) return;
    const data = await res.json();
    if (Array.isArray(data.triangles)) {
      drawTriangles(data.triangles);
    }
    statsEl.textContent = formatStats(data.stats);
  } catch (err) {
    statsEl.textContent = 'Error consultando el master.';
  }
}

window.addEventListener('DOMContentLoaded', () => {
  fetchData();
  setInterval(fetchData, 1000);
});
